using sv_765558e758d04f4db1a1fe86067d7813.Models;

namespace sv_765558e758d04f4db1a1fe86067d7813.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_765558e758d04f4db1a1fe86067d7813.Models;

namespace sv_765558e758d04f4db1a1fe86067d7813.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with tomato, mozzarella, and basil.", 30),
            new(2, "Spaghetti Carbonara", "Creamy pasta with guanciale, egg yolk, and pecorino romano.", 25),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream.", 45),
        },
        [2] = new List<Recipe>
        {
            new(4, "Chicken Tikka Masala", "Grilled chicken in a rich, spiced tomato-cream sauce.", 50),
            new(5, "Palak Paneer", "Fresh spinach curry with soft paneer cubes.", 35),
            new(6, "Biryani", "Fragrant basmati rice layered with spiced meat and herbs.", 60),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Marinated pork tacos with pineapple, onion, and cilantro.", 40),
            new(8, "Guacamole", "Fresh avocado dip with lime, cilantro, and jalapeño.", 10),
            new(9, "Churros", "Fried dough pastry coated in cinnamon sugar with chocolate sauce.", 30),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        return RecipesByCuisine.TryGetValue(cuisineId, out var recipes)
            ? recipes
            : new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_765558e758d04f4db1a1fe86067d7813.Models
@using sv_765558e758d04f4db1a1fe86067d7813.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes — Cuisine #@CuisineId</h1>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex justify-content-between align-items-center" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm" @onclick="Retry">Retry</button>
    </div>
}

@if (_recipes is null && _errorMessage is null)
{
    <p><em>Loading recipes…</em></p>
}
else if (_recipes is not null)
{
    @if (_isRefreshing)
    {
        <div class="text-muted mb-2"><small>Refreshing…</small></div>
    }

    @{
        var displayed = Sort switch
        {
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
            "newest" => _recipes.OrderByDescending(r => r.Id).ToList(),
            _ => _recipes,
        };
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in displayed)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes min</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;

    private CancellationTokenSource? _loadCts;
    private readonly CancellationTokenSource _disposeCts = new();
    private int _lastLoadedCuisineId;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload when the cuisine changes, not when sort changes.
        if (CuisineId == _lastLoadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load for a previous cuisine.
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }

        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
        var cts = _loadCts;

        _errorMessage = null;
        _isRefreshing = _recipes is not null;
        _lastLoadedCuisineId = CuisineId;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            // Guard against a late completion after cancellation.
            if (cts.Token.IsCancellationRequested)
            {
                return;
            }

            _recipes = result;
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Expected when the user switched cuisines or navigated away.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Dispose();
    }
}

